#include <cstdio>
#include <cstring>
#include <algorithm>
using namespace std;
const long long MOD = 1000000007;

struct Mat {
    int mat[31][31], size;
    Mat operator*(const Mat &other) const {
        Mat res; res.size = size;
        for (int i = 0; i <= size; ++i)
            for (int j = 0; j <= size; ++j) {
                res.mat[i][j] = 0;
                for (int k = 0; k <= size; ++k)
                    res.mat[i][j] = ((long long)mat[i][k] * other.mat[k][j] + res.mat[i][j]) % MOD;
            }
        return res;
    }
};

int main() {
    long long N, K;
    scanf("%lld %lld", &N, &K);
    int digits[70], count = 0;
    while (N > 0) {
        digits[count++] = N % K;
        N /= K;
    }

    static Mat matrices[64][30], prefix[64][30], suffix[64][30], answer;
    for (int i = 0; i < K; ++i) {
        for (int j = 0; j <= K; ++j) {
            matrices[0][i].mat[j][j] = 1;
            matrices[0][i].mat[j][i] = 1;
        }
        matrices[0][i].size = K;
    }

    prefix[0][0] = matrices[0][0];
    suffix[0][K - 1] = matrices[0][K - 1];

    for (int i = 1; i < K; ++i)
        prefix[0][i] = prefix[0][i - 1] * matrices[0][i];

    for (int i = K - 2; i >= 0; --i)
        suffix[0][i] = matrices[0][i] * suffix[0][i + 1];

    for (int i = 1; i < count; ++i) {
        matrices[i][0] = suffix[i - 1][0];
        for (int j = 1; j < K; ++j)
            matrices[i][j] = suffix[i - 1][j] * prefix[i - 1][j - 1];

        prefix[i][0] = matrices[i][0];
        suffix[i][K - 1] = matrices[i][K - 1];

        for (int j = 1; j < K; ++j)
            prefix[i][j] = prefix[i][j - 1] * matrices[i][j];

        for (int j = K - 2; j >= 0; --j)
            suffix[i][j] = matrices[i][j] * suffix[i][j + 1];
    }

    answer.mat[0][K] = 1;
    answer.size = K;
    answer = answer * prefix[count - 1][digits[count - 1] - 1];

    int lastDigit = digits[count - 1];
    for (int i = count - 2; i >= 0; --i) {
        for (int j = 0; j < digits[i]; ++j)
            answer = answer * matrices[i][(j + lastDigit) % K];
        lastDigit += digits[i];
    }

    long long totalSum = 0;
    for (int i = 0; i <= K; ++i)
        totalSum += answer.mat[0][i];

    printf("%lld\n", totalSum % MOD);
    return 0;
}
